      },
      "titleFontWeight": {
        "dataType": "select",
        "displayName": "Title Font Weight",
        "defaultValue": "300",
        "options": ["300", "400", "500"],
        "group": "Typography"
      },
      "preloadDistance": {
        "dataType": "select",
        "displayName": "Preload Distance (px)",
        "defaultValue": "400",
        "options": ["200", "300", "400", "500", "600"],
        "group": "Performance"
      },
