const MANIFEST = {
  "type": "Loading.EntryPreloader",
  "description": "Counting entry preloader with a wordmark and a wipe reveal. A craft signal for studio and portfolio sites — skipped entirely under reduced motion.",
  "editorElement": {
    "selector": ".entry-preloader",
    "displayName": "Entry Preloader",
    "archetype": "container",
    "data": {
      "wordmark": { "dataType": "text", "displayName": "Wordmark", "defaultValue": "NORTHGATE", "group": "Content" },
