      "accentColor": { "dataType": "color", "displayName": "Accent", "defaultValue": "#C2803A", "group": "Colors" },
      "pageColor": { "dataType": "color", "displayName": "Revealed Background", "defaultValue": "#F5F3EE", "group": "Colors" },
      "pageTextColor": { "dataType": "color", "displayName": "Revealed Text", "defaultValue": "#141414", "group": "Colors" },
      "wordmarkSize": { "dataType": "number", "displayName": "Wordmark Size (px)", "defaultValue": 62, "group": "Typography" },
      "letterSpacing": { "dataType": "select", "displayName": "Wordmark Tracking", "defaultValue": "0.16", "options": ["0", "0.06", "0.16", "0.3", "0.5"], "group": "Typography" }
    },
    "layout": { "resizeDirection": "horizontalAndVertical", "contentResizeDirection": "vertical" }
  }
};

function Component({ config = {} }) {
  const loaderBg = config?.backgroundColor || '#141414';
  const loaderText = config?.loaderTextColor || '#F5F3EE';
  const accent = config?.accentColor || '#C2803A';
  const pageBg = config?.pageColor || '#F5F3EE';
  const pageText = config?.pageTextColor || '#141414';
  const duration = parseInt(config?.duration || '2200', 10);
  const counterStyle = config?.counterStyle || 'percent';
  const exitStyle = config?.exitStyle || 'wipe-up';
  const replayable = config?.replayable !== false;
  const wordmarkSize = Math.max(18, Math.min(160, parseInt(config?.wordmarkSize, 10) || 62));
  const tracking = parseFloat(config?.letterSpacing || '0.16');

  const reduceMotion = typeof window !== 'undefined' && window.matchMedia
    ? window.matchMedia('(prefers-reduced-motion: reduce)').matches : false;

  const [progress, setProgress] = React.useState(reduceMotion ? 100 : 0);
  const [done, setDone] = React.useState(reduceMotion);
  const [runId, setRunId] = React.useState(0);
  const rafRef = React.useRef(null);

  React.useEffect(function () {
    if (reduceMotion) { setProgress(100); setDone(true); return; }
    setProgress(0); setDone(false);
    const start = (typeof performance !== 'undefined' ? performance.now() : Date.now());
    const tick = function (now) {
      const t = Math.min(1, (now - start) / duration);
      // ease-out so it decelerates into 100 rather than snapping
      const eased = 1 - Math.pow(1 - t, 2.2);
      setProgress(Math.round(eased * 100));
      if (t < 1) { rafRef.current = requestAnimationFrame(tick); }
      else { setProgress(100); setTimeout(function () { setDone(true); }, 260); }
    };
    rafRef.current = requestAnimationFrame(tick);
    return function () { if (rafRef.current) cancelAnimationFrame(rafRef.current); };
  }, [duration, reduceMotion, runId]);

  const exitStyles = function () {
    if (!done) return { transform: 'none', opacity: 1, clipPath: 'inset(0 0 0 0)' };
    if (exitStyle === 'fade') return { opacity: 0 };
    if (exitStyle === 'split') return { clipPath: 'inset(0 50% 0 50%)' };
    if (exitStyle === 'curtain') return { clipPath: 'inset(0 0 100% 0)' };
    return { transform: 'translateY(-100%)' };
  };

  return (
    <div className="entry-preloader" style={{
      position: 'relative', width: '100%', minHeight: '620px', overflow: 'hidden',
      backgroundColor: pageBg, color: pageText,
      fontFamily: '-apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif',
      WebkitFontSmoothing: 'antialiased'
    }}>
      {/* revealed page */}
      <div style={{
        padding: '110px 40px', maxWidth: '900px', margin: '0 auto',
        opacity: done ? 1 : 0,
        transform: done ? 'translateY(0)' : 'translateY(18px)',
        transition: reduceMotion ? 'none' : 'opacity 700ms ease-out 180ms, transform 700ms cubic-bezier(0.22,1,0.36,1) 180ms'
      }}>
        <h2 style={{
          fontSize: 'clamp(28px, 5vw, 52px)', fontWeight: 500, lineHeight: 1.08,
          letterSpacing: '-0.025em', margin: '0 0 18px', maxWidth: '16ch', textWrap: 'balance'
        }}>{config?.revealedHeading || 'We make things that hold up.'}</h2>
        <p style={{ fontSize: '17px', lineHeight: 1.65, maxWidth: '54ch', margin: 0, opacity: 0.72 }}>
          {config?.revealedBody}
        </p>
        {replayable ? (
          <button onClick={function () { setRunId(runId + 1); }} style={{
            marginTop: '34px', padding: '11px 20px', font: 'inherit', fontSize: '13px',
            cursor: 'pointer', color: pageText, backgroundColor: 'transparent',
            border: '1px solid ' + pageText, borderRadius: '999px'
          }}>Replay intro</button>
        ) : null}
      </div>

      {/* loader overlay */}
      <div aria-hidden={done ? 'true' : undefined} style={{
        position: 'absolute', inset: 0, backgroundColor: loaderBg, color: loaderText,
        display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center',
        gap: '26px', padding: '40px', pointerEvents: done ? 'none' : 'auto',
        transition: reduceMotion ? 'none' : 'transform 900ms cubic-bezier(0.76,0,0.24,1), opacity 600ms ease-out, clip-path 900ms cubic-bezier(0.76,0,0.24,1)',
        ...exitStyles()
      }}>
        <div style={{
          fontSize: 'clamp(24px, ' + (wordmarkSize / 10) + 'vw, ' + wordmarkSize + 'px)',
          fontWeight: 500, letterSpacing: tracking + 'em', textIndent: tracking + 'em',
          lineHeight: 1, textAlign: 'center'
        }}>{config?.wordmark || 'NORTHGATE'}</div>

        {config?.tagline ? (
          <div style={{ fontSize: '12.5px', opacity: 0.55, letterSpacing: '0.04em', textAlign: 'center' }}>
            {config.tagline}
          </div>
        ) : null}

        {(counterStyle === 'bar' || counterStyle === 'both') ? (
          <div style={{ width: 'min(420px, 70%)', height: '2px', backgroundColor: 'rgba(255,255,255,0.18)' }}>
            <div style={{
              width: progress + '%', height: '100%', backgroundColor: accent,
              transition: 'width 120ms linear'
            }} />
          </div>
        ) : null}

        {(counterStyle === 'percent' || counterStyle === 'both') ? (
          <div role="status" aria-live="polite" style={{
            fontFamily: 'ui-monospace, SFMono-Regular, Menlo, monospace',
            fontSize: '13px', letterSpacing: '0.1em', color: accent,
            fontVariantNumeric: 'tabular-nums'
          }}>{String(progress).padStart(3, '0')}</div>
        ) : null}
      </div>
    </div>
  );
}
